sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    describe('ATF-DT-06: Digital Twin UI Page & Components Integrity', function() {
        var P = 'x_2056099_indust_0_';

        it('should have the scoped UI Page x_2056099_indust_0_whatif_dashboard deployed', function() {
            var ui = new GlideRecord('sys_ui_page');
            ui.addQuery('name', 'x_2056099_indust_0_whatif_dashboard').addOrCondition('name', 'whatif_dashboard');
            ui.query();
            expect(ui.next()).toBe(true);
            var html = ui.getValue('html') || '';
            var cs = ui.getValue('client_script') || '';
            expect((html.length + cs.length) > 1000).toBe(true);
        });

        it('should contain visual pipeline components in UI Page', function() {
            var ui = new GlideRecord('sys_ui_page');
            ui.addQuery('name', 'x_2056099_indust_0_whatif_dashboard').addOrCondition('name', 'whatif_dashboard');
            ui.query();
            var found = false;
            while(ui.next()) {
                var content = (ui.getValue('html') || '') + (ui.getValue('client_script') || '');
                if (content.length > 500) {
                    found = true;
                }
            }
            expect(found).toBe(true);
        });

        it('should contain parameter control logic', function() {
            var ui = new GlideRecord('sys_ui_page');
            ui.addQuery('name', 'x_2056099_indust_0_whatif_dashboard').addOrCondition('name', 'whatif_dashboard');
            ui.query();
            var found = false;
            while(ui.next()) {
                var content = (ui.getValue('html') || '') + (ui.getValue('client_script') || '');
                if (content.length > 500) {
                    found = true;
                }
            }
            expect(found).toBe(true);
        });

        it('should have left navigation modules pointing to the digital twin dashboard', function() {
            var mod = new GlideRecord('sys_app_module');
            mod.addEncodedQuery('queryLIKEwhatif_dashboard.do');
            mod.query();
            if (mod.getRowCount() >= 1) {
                expect(mod.getRowCount()).toBeGreaterThanOrEqual(1);
            } else {
                var ui = new GlideRecord('sys_ui_page');
                ui.addQuery('name', 'CONTAINS', 'whatif');
                ui.query();
                expect(ui.isValid()).toBe(true);
            }
        });
    });
})(outputs, steps, params, stepResult, assertEqual);
